#pragma once
#include "kstationFlashStateTask.h"
namespace kstation {
class StartupButtonScanTask final {
public:enum class Stage{Input,WriteInput,LowSelect,WriteLowSelect,RetainDelay,Settling,RetainInner,Delay,DecrementDelay,RepeatDelay,RestoreInner,DecrementSettling,RepeatSettling,RestoreDelay,ReadLow,HighSelect,WriteHighSelect,ReadHigh,Release,WriteRelease,Output,WriteOutput,Return,Complete};Stage stage()const{return stage_;}bool complete()const{return stage_==Stage::Complete;}bool secondDelay()const{return second_;}uint16_t value()const{return value_;}unsigned nextClocks(const FlashCredits&c)const{switch(stage_){case Stage::WriteInput:case Stage::WriteLowSelect:case Stage::ReadLow:case Stage::WriteHighSelect:case Stage::ReadHigh:case Stage::WriteRelease:case Stage::WriteOutput:return 4;case Stage::RetainDelay:case Stage::RetainInner:return c.pushWord;case Stage::Settling:case Stage::Delay:return 6;case Stage::RestoreInner:case Stage::RestoreDelay:return c.popWord;case Stage::Return:return c.ret;case Stage::Complete:return 0;default:return 3;}}template<class R,class W>unsigned advanceBefore(unsigned budget,const FlashCredits&c,R&&read,W&&write){auto cost=nextClocks(c);if(!cost||cost>budget)return 0;auto next=Stage(unsigned(stage_)+1);switch(stage_){case Stage::WriteInput:write(true,0);break;case Stage::WriteLowSelect:write(false,0x10);break;case Stage::Settling:settling_=1;break;case Stage::Delay:delay_=2663;break;case Stage::DecrementDelay:--delay_;break;case Stage::RepeatDelay:if(delay_)next=Stage::DecrementDelay;break;case Stage::DecrementSettling:--settling_;break;case Stage::RepeatSettling:if(settling_)next=Stage::RetainInner;break;case Stage::RestoreDelay:next=second_?Stage::ReadHigh:Stage::ReadLow;break;case Stage::ReadLow:value_=uint8_t(read(false));break;case Stage::WriteHighSelect:write(false,0x18);second_=true;next=Stage::RetainDelay;break;case Stage::ReadHigh:value_|=uint16_t(uint8_t(read(true)))<<8;break;case Stage::WriteRelease:write(false,0x40);break;case Stage::WriteOutput:write(true,255);break;default:break;}stage_=next;return cost;}
private:Stage stage_=Stage::Input;bool second_=false;unsigned settling_=0,delay_=0;uint16_t value_=0;};
class StartupButtonWaitTask final {
public:enum class Kind{Stable,Released,Pressed,Confirm,Probe};enum class Stage{Scan,RetainCandidate,Compare,Select,RetainDelay,Settling,RetainInner,Delay,DecrementDelay,RepeatDelay,RestoreInner,DecrementSettling,RepeatSettling,RestoreDelay,ScanAgain,CompareAgain,Repeat,Return,PressChild,CompareConfirm,CompareUpdate,SelectUpdate,CompareCopy,SelectCopy,Complete};StartupButtonWaitTask(Kind kind=Kind::Stable):kind_(kind){}Kind kind()const{return kind_;}Stage stage()const{return stage_;}bool complete()const{return stage_==Stage::Complete;}bool awaiting()const{return waiting_;}void resume(uint16_t value){value_=value;waiting_=false;}uint16_t value()const{return value_;}unsigned nextClocks(const FlashCredits&c)const{if(waiting_||complete())return 0;switch(stage_){case Stage::Scan:return kind_==Kind::Stable?c.call:c.shortCall;case Stage::ScanAgain:return kind_==Kind::Stable?c.call:c.shortCall;case Stage::PressChild:return c.shortCall;case Stage::Compare:case Stage::CompareConfirm:case Stage::CompareUpdate:case Stage::CompareCopy:case Stage::Settling:case Stage::Delay:return 6;case Stage::CompareAgain:return kind_==Kind::Stable?3:6;case Stage::RetainDelay:case Stage::RetainInner:return c.pushWord;case Stage::RestoreInner:case Stage::RestoreDelay:return c.popWord;case Stage::Return:return c.ret;default:return 3;}}unsigned advanceBefore(unsigned budget,const FlashCredits&c){auto cost=nextClocks(c);if(!cost||cost>budget)return 0;auto next=Stage(unsigned(stage_)+1);switch(stage_){case Stage::Scan:waiting_=true;next=kind_==Kind::Stable?Stage::RetainCandidate:kind_==Kind::Confirm?Stage::PressChild:kind_==Kind::Probe?Stage::CompareUpdate:Stage::Compare;break;case Stage::RetainCandidate:candidate_=value_;next=Stage::RetainDelay;break;case Stage::Select:if(kind_==Kind::Pressed)next=value_==0xffff?Stage::Scan:Stage::Return;else next=value_==0xffff?Stage::RetainDelay:Stage::Scan;break;case Stage::Settling:settling_=10;break;case Stage::Delay:delay_=2663;break;case Stage::DecrementDelay:--delay_;break;case Stage::RepeatDelay:if(delay_)next=Stage::DecrementDelay;break;case Stage::DecrementSettling:--settling_;break;case Stage::RepeatSettling:if(settling_)next=Stage::RetainInner;break;case Stage::ScanAgain:waiting_=true;break;case Stage::Repeat:next=value_==(kind_==Kind::Stable?candidate_:0xffff)?Stage::Return:Stage::Scan;break;case Stage::Return:next=Stage::Complete;break;case Stage::PressChild:waiting_=true;break;case Stage::CompareConfirm:next=Stage::Return;break;case Stage::SelectUpdate:if(value_==0xff8f)next=Stage::Complete;break;case Stage::SelectCopy:next=value_==0x8fff?Stage::Complete:Stage::Return;break;default:break;}stage_=next;return cost;}
private:Kind kind_;Stage stage_=Stage::Scan;uint16_t value_=0,candidate_=0;unsigned settling_=0,delay_=0;bool waiting_=false;};
class StartupBootCopyTask final {
public:enum class Stage{FirstPrompt,FirstText,FirstConfirm,SelectFirst,SecondPrompt,SecondText,SecondConfirm,SelectSecond,Marker,WriteMarker,Return,Complete};Stage stage()const{return stage_;}bool complete()const{return stage_==Stage::Complete;}bool awaiting()const{return waiting_;}void resume(bool confirmed){confirmed_=confirmed;waiting_=false;}unsigned nextClocks(const FlashCredits&c)const{if(waiting_||complete())return 0;switch(stage_){case Stage::FirstPrompt:case Stage::SecondPrompt:return 9;case Stage::FirstText:case Stage::SecondText:return c.call;case Stage::FirstConfirm:case Stage::SecondConfirm:return c.shortCall;case Stage::WriteMarker:return 9+c.write;case Stage::Return:return c.ret;default:return 3;}}template<class W>unsigned advanceBefore(unsigned budget,const FlashCredits&c,W&&write){auto cost=nextClocks(c);if(!cost||cost>budget)return 0;auto next=Stage(unsigned(stage_)+1);switch(stage_){case Stage::FirstText:case Stage::SecondText:case Stage::FirstConfirm:case Stage::SecondConfirm:waiting_=true;break;case Stage::SelectFirst:case Stage::SelectSecond:if(!confirmed_)next=Stage::Return;break;case Stage::WriteMarker:write(0xaa);break;default:break;}stage_=next;return cost;}
private:Stage stage_=Stage::FirstPrompt;bool confirmed_=false,waiting_=false;};
}
